 INSERT INTO population_top3000_202608_202609_v1.pipeline_event(event,details) VALUES('PRACTICAL_COHORT_INDEPENDENT_SOURCE_REVIEW_V1','{"reviewer": "/root/cohort_reviewer", "producer": "/root/cohort_producer", "assignment_event_id": 23382, "review_kind": "PRACTICAL_HISTORICAL_SNAPSHOT_SOURCE_REVIEW", "result": "PASS_CANDIDATE_SOURCE_CHECKS_ONLY", "checked_at": "2026-10-24T11:52:00.639716Z", "selected_company_count": 3000, "selected_instrument_point_count": 3000, "eligible_company_count": 4331, "selected_adr_count": 247, "selected_composite_figi_multiple_issuers": 0, "selected_share_class_figi_multiple_issuers": 0, "retained_original_bodies_independently_rehashed": 3014, "body_hash_mismatches": 0, "census_record_hash_mismatches": 0, "overview_record_hash_mismatches": 0, "identity_listing_field_mismatches": 0, "selection_proxy_field_mismatches": 0, "overview_request_dates": "All 3000 are 2026-08-03", "census_request_dates": "14 pages: first direct request date 2026-08-03; 13 exact chained cursors independently decoded with date=2026-08-03", "cursor_chain_mismatches": 0, "cursor_date_mismatches": 0, "direct_date_check_correction": "2722 census rows had cursor-only request parameters, not a conflicting date. Exact chain and decoded date checks resolved this initial missing-direct-date diagnostic.", "snapshot_sha256": "2dc0f766befed6de6b052221c3c87482d507ba1bad931cbb98654eb3af899bec", "company_manifest_sha256": "4134b415e2c26fcde9fced749c0d54ef51376e23f0d2f8c6ce9ef562f9fab99f", "instrument_manifest_sha256": "d21914d0a729a34c6c5650fd84dd12f8e6f46f2cee0dac415b105bb3474b3e0e", "source_snapshot_sha256": "c0847f36b52cb7e029424f1434bedc7e48ac8055d9a1590bc08ed87e60c77825", "policy_sha256": "3e49d661fcdb8533e5ce88a85689b41e9dde71eeae2dc8578c9e31f9ae1738bb", "membership_accepted": false, "original_historical_receipt_proven": false, "full_period_instrument_completeness": false, "financial_facts_verified": false, "unverified_rank_date_share_flags_preserved": 3000, "new_provider_cal